<script setup lang="ts">
import FiltroCodigoAutocomplete from './FiltroCodigoAutocomplete.vue';import type { EtapaEngrase, FiltroCodigoSugerencia, FiltrosEngraseQuery, TipoEquipoEngrase, TipoFiltroEngrase } from '@/stores/dbequipos/engrase/filtrosEngrase.types'
defineProps<{filters:FiltrosEngraseQuery;tiposEquipo:TipoEquipoEngrase[];tiposFiltro:TipoFiltroEngrase[];etapas:EtapaEngrase[];sugerenciasCodigo:FiltroCodigoSugerencia[];loading:boolean;loadingSugerencias:boolean}>();const emit=defineEmits<{updateFilters:[Partial<FiltrosEngraseQuery>];searchCodeSuggestions:[string];selectCodeSuggestion:[FiltroCodigoSugerencia];clearCode:[]}>();
</script>
<template><section class="toolbar" aria-label="Filtros de equipos"><FiltroCodigoAutocomplete :model-value="filters.codigoExactoSeleccionado??''" :sugerencias="sugerenciasCodigo" :loading="loadingSugerencias" @update:model-value="emit('updateFilters',{codigoExactoSeleccionado:null})" @search="emit('searchCodeSuggestions',$event)" @select="emit('selectCodeSuggestion',$event)" @clear="emit('clearCode')"/><label class="field"><span>Tipo de equipo</span><select :value="filters.tipoEquipoId??''" @change="emit('updateFilters',{tipoEquipoId:Number(($event.target as HTMLSelectElement).value)||null})"><option value="">Todos</option><option v-for="item in tiposEquipo" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label class="field"><span>Modelo</span><input :value="filters.modelo" placeholder="Todos los modelos" @input="emit('updateFilters',{modelo:($event.target as HTMLInputElement).value})"/></label><label class="field"><span>Etapa</span><select :value="filters.etapaId??''" @change="emit('updateFilters',{etapaId:Number(($event.target as HTMLSelectElement).value)||null})"><option value="">Todas / Sin etapa</option><option v-for="item in etapas" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label class="field"><span>Tipo de filtro</span><select :value="filters.tipoFiltroId??''" @change="emit('updateFilters',{tipoFiltroId:Number(($event.target as HTMLSelectElement).value)||null})"><option value="">Todos</option><option v-for="item in tiposFiltro" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><fieldset class="state"><legend>Estado</legend><button type="button" :class="{selected:filters.estadoEquipo==='activo'}" @click="emit('updateFilters',{estadoEquipo:'activo'})">Activos</button><button type="button" :class="{selected:filters.estadoEquipo==='descartado'}" @click="emit('updateFilters',{estadoEquipo:'descartado'})">Descartados</button></fieldset></section></template>
<style scoped>.toolbar{display:grid;grid-template-columns:minmax(210px,1.5fr) repeat(4,minmax(130px,1fr)) auto;gap:1rem;padding:1.2rem;border:1px solid #e6edf7;border-radius:1rem;background:#fff;box-shadow:0 7px 20px #1e3a5f0a}.field span,.state legend{display:block;margin-bottom:.45rem;font-size:.73rem;font-weight:800;color:#172554}.field input,.field select{width:100%;height:44px;border:1px solid #dbe4f0;border-radius:.7rem;padding:0 .7rem;background:#fff;color:#172554}.state{border:0;padding:0;display:flex;gap:.4rem;flex-wrap:wrap}.state legend{width:100%}.state button{height:44px;padding:0 .7rem;border:1px solid #dbe4f0;border-radius:.6rem;font-size:.75rem;color:#64748b}.state button.selected{border-color:#16a34a;background:#f0fdf4;color:#15803d}@media(max-width:1100px){.toolbar{grid-template-columns:repeat(3,1fr)}}@media(max-width:650px){.toolbar{grid-template-columns:1fr}.state button{flex:1}}</style>
